INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (147, 303, '一些特殊的符号', '../', '<p></p><p><span style="font-family:宋体;font-size:10.5pt;"><span style="color:#202124;font-family:arial, sans-serif;background-color:#FFFFFF;">㎡ (square meter)</span><br/> </span></p> <p><span style="font-family:宋体;font-size:10.5pt;">±</span></p> <p><span style="color:#000000;font-family:Arial;font-size:10.5pt;">ºC</span></p> <p><span style="font-family:宋体;font-size:10.5pt;"><span>波浪线</span> <span>符号</span> </span><span style="font-family:Arial;font-size:10.5pt;"><span>﹏</span></span></p> <p><u><span style="color:#2200CC;font-family:Arial;font-size:13.5pt;text-decoration:underline;"><span>用</span>√</span></u><u><span style="color:#CC0033;font-family:Arial;font-size:13.5pt;text-decoration:underline;"><span>符号</span></span></u><u><span style="color:#2200CC;font-family:Arial;font-size:13.5pt;text-decoration:underline;"><span>。错用</span>×</span></u><u><span style="color:#CC0033;font-family:Arial;font-size:13.5pt;text-decoration:underline;"><span>符号</span></span></u></p> <p><span style="color:#000000;font-family:Arial;font-size:10.5pt;">Ω</span></p> <p></p> <p><span style="color:#000000;font-family:Arial;font-size:10.5pt;"><span>＜</span></span></p> <p><span style="color:#000000;font-family:Arial;font-size:10.5pt;"><span>＞</span></span></p> <p><span style="color:#000000;font-family:Arial;font-size:10.5pt;">≤<span>、</span><span>≥</span></span></p>', '2026-09-06 20:58:45');
INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (147, 304, '单位换算 -公制到英制换算', '../', '<p></p><p align="justify" style="text-align:justify;"> 密耳是一个长度的单位，代表千分之一英寸，1mil（密尔）=25.39999918μm（微米）<br/> grammage 1 lb=3.75gsm,1LB=0.453592Kg lb指磅（重量单位） <br/> 1码（yard) = 91.44 厘米<br/> 1英尺(feet) = 0.3048 米 30.5cm<br/></p> <span style=''font-family:"font-size:10.5pt;''> <p align="justify" style="text-align:justify;"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"><span>公制到英制换算</span> </span></p> <p><span style="font-family:宋体;font-size:10.5pt;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;">Linear Measure </span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">长度</span></span></span></p> <p><span style="font-family:宋体;font-size:10.5pt;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;">1 millimetre </span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">毫米</span></span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">=0.03937 inch </span></span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">英寸</span></span></span></p> <p><span style="font-family:宋体;font-size:10.5pt;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;">1 centimetre </span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">厘米</span></span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">=10 mm. </span></span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">毫米</span></span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">=0.3937 inch </span></span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">英寸</span></span></span></p> <p><span style="font-family:宋体;font-size:10.5pt;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;">1 decimetre </span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">分米</span></span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">=10 cm. </span></span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">厘米</span></span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">=3.937 inches </span></span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">英寸</span></span></span></p> <p><span style="font-family:宋体;font-size:10.5pt;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;">1 metre </span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">米</span></span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">=10 dm. </span></span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">分米</span></span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">=1.0936 yards </span></span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">码</span></span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">=3.2808 feet </span></span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">英尺</span></span></span></p> <p><span style="font-family:宋体;font-size:10.5pt;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;">1 decametre </span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">十米</span></span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">=10 m. </span></span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">米</span></span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">=10.936 yards </span></span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">码</span></span></span></p> <p><span style="font-family:宋体;font-size:10.5pt;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;">1 hectometre </span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">百米</span></span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">=100 m. </span></span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">米</span></span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">=109.4 yards </span></span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">码</span></span></span></p> <p><span style="font-family:宋体;font-size:10.5pt;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;">1 kilometre </span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">千米</span></span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">=1000 m. </span></span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">米</span></span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">=0.6214 mile </span></span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">英里</span></span></span></p> <p><span style="font-family:宋体;font-size:10.5pt;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;">1 mile marin </span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">海里</span></span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">=1852 m. </span></span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">米</span></span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">=1.1500 mile </span></span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">英里 </span></span></span></p> <p><span style="font-family:宋体;font-size:10.5pt;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;">Square Measure </span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">面积</span></span></span></p> <p><span style="font-family:宋体;font-size:10.5pt;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;">1 square centimetre </span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">平方厘米</span></span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">=0.155 sq.inch </span></span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">平方英寸</span></span></span></p> <p><span style="font-family:宋体;font-size:10.5pt;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;">1 square metre </span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">平方米</span></span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">=1.196 sq.yards </span></span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">平方码</span></span></span></p> <p><span style="font-family:宋体;font-size:10.5pt;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;">1 are </span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">公亩</span></span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">=100 square metres </span></span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">平方米</span></span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">=119.6 sq.yards </span></span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">平方码</span></span></span></p> <p><span style="font-family:宋体;font-size:10.5pt;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;">1 hectare </span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">公顷</span></span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">=100 ares </span></span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">公亩</span></span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">=2.471 acres </span></span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">英亩</span></span></span></p> <p><span style="font-family:宋体;font-size:10.5pt;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;">1 square kilometre </span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">平方公里</span></span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">=0.386 sq.mile </span></span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">平方英里 </span></span></span></p> <p><span style="font-family:宋体;font-size:10.5pt;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;">Cubic Measure </span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">体积</span></span></span></p> <p><span style="font-family:宋体;font-size:10.5pt;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;">1 cubic centimetre </span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">立方厘米</span></span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">=0.061 cu.inch </span></span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">立方英寸</span></span></span></p> <p><span style="font-family:宋体;font-size:10.5pt;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;">1 cubic metre </span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">立方米</span></span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">=1.308 cu.yards </span></span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">立方码 </span></span></span></p> <p><span style="font-family:宋体;font-size:10.5pt;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;">Capacity Measure </span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">容积</span></span></span></p> <p><span style="font-family:宋体;font-size:10.5pt;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;">1 millilitre </span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">毫升</span></span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">=0.002 pint (British) </span></span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">英制品脱</span></span></span></p> <p><span style="font-family:宋体;font-size:10.5pt;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;">1 centilitre </span><s